card-hover-glow:
/* Glow Card */
.roycss-card-hover-glow {
  background: oklch(0.208 0.04 265.75);
  border: 1px solid color-mix(in oklch, oklch(0.696 0.149 162.48) 20%, transparent);
  border-radius: 16px;
  padding: 24px;
  color: oklch(0.929 0.013 255.51);
