  align-items: center;
  justify-content: center;
  color: oklch(1 0 89.88);
  font-size: 12px;
  font-weight: 600;
}

.roycss-border-clip-path::before {
  content: '';
  position: absolute;
  inset: 3px;
  background: oklch(0.208 0.04 265.75);
  clip-path: polygon(12px 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%, 0 12px);
}

