nav-accordion:
/* Accordion Menu */
.roycss-nav-accordion {
  position: relative;
  inline-size: 180px;
  block-size: 34px;
  background: color-mix(in oklch, oklch(1 0 89.88) 4%, transparent);
  border: 1px solid color-mix(in oklch, oklch(1 0 89.88) 12%, transparent);
  border-radius: 8px;
  font: 11px/1 system-ui, sans-serif;
