nav-pagination:
/* Pagination Pulse */
.roycss-nav-pagination {
  position: relative;
  inline-size: 200px;
  block-size: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  font: 11px/1 system-ui, sans-serif;
  color: color-mix(in oklch, oklch(1 0 89.88) 60%, transparent);
  letter-spacing: 0.3em;
}
