.roycss-nav-pagination::after {
  content: "";
  position: absolute;
  inset-block-start: 50%;
  inset-inline-start: 50%;
  inline-size: 18px;
  block-size: 18px;
  margin: -9px 0 0 -9px;
  border: 1.5px solid oklch(0.696 0.149 162.48);
  border-radius: 50%;
