slide-in-bottom:
/* Slide In Bottom */
.roycss-slide-in-bottom {
  animation: roy-slide-in-bottom 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) both;
}

@keyframes roy-slide-in-bottom {
  from {
    transform: translate3d(0, 100%, 0);
    visibility: visible;
  }
