slide-out-bottom:
/* Slide Out Bottom */
.roycss-slide-out-bottom {
  animation: roy-slide-out-bottom 0.6s cubic-bezier(0.55, 0.085, 0.68, 0.53) both;
}

@keyframes roy-slide-out-bottom {
  from {
    transform: translate3d(0, 0, 0);
  }
  to {
    visibility: hidden;
    transform: translate3d(0, 100%, 0);
  }
}

slide-out-left:
/* Slide Out Left */
