}

@keyframes roy-cursor-glow-orbit {
  0% { transform: translate(-22px, -10px); }
  25% { transform: translate(0, -20px); }
  50% { transform: translate(22px, -10px); }
  75% { transform: translate(0, 12px); }
  100% { transform: translate(-22px, -10px); }
}

cursor-trail:
