  block-size: 26px;
  margin: -13px 0 0 -1px;
}

@keyframes roy-cursor-crosshair-move {
  0%, 100% { transform: translate(-22px, -12px); }
  50% { transform: translate(22px, 14px); }
}

cursor-arrow-bounce:
