  inset-block-end: -10px;
  inline-size: 24px;
  block-size: 24px;
  border-radius: 50%;
  background: radial-gradient(circle, color-mix(in oklch, oklch(0.833 0 89.88) 40%, transparent) 0%, color-mix(in oklch, oklch(0.673 0 89.88) 15%, transparent) 60%, transparent 100%);
