@keyframes roy-particle-smoke-rise {
  0%   { transform: translate(0, 0) scale(0.4); opacity: 0; }
  20%  { opacity: 0.7; }
  100% { transform: translate(var(--tx), -180px) scale(2.2); opacity: 0; }
}

