visual-glitch-distort:
/* Glitch Distort */
.roycss-visual-glitch-distort {
  position: relative;
  inline-size: 180px;
  block-size: 120px;
  border-radius: 14px;
  border: none;
  background: linear-gradient(135deg, oklch(0.656 0.212 354.31), oklch(0.606 0.219 292.72), oklch(0.715 0.126 215.22));
  overflow: hidden;
}

.roycss-visual-glitch-distort > div { display: none; }

.roycss-visual-glitch-distort::before,
.roycss-visual-glitch-distort::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  mix-blend-mode: screen;
}

.roycss-visual-glitch-distort::before {
  background: linear-gradient(135deg, oklch(0.632 0.254 21.75), oklch(0.632 0.254 21.75), oklch(0.715 0.126 215.22));
  animation: roy-visual-glitch-1 1.5s steps(2) infinite;
}

.roycss-visual-glitch-distort::after {
  background: linear-gradient(135deg, oklch(0.901 0.157 187.23), oklch(0.656 0.212 354.31), oklch(0.901 0.157 187.23));
  animation: roy-visual-glitch-2 1.7s steps(2) infinite;
}

@keyframes roy-visual-glitch-1 {
  0%, 100% { clip-path: inset(0 0 95% 0);  transform: translate(0); }
  20%      { clip-path: inset(20% 0 60% 0); transform: translate(-4px, 2px); }
  40%      { clip-path: inset(50% 0 30% 0); transform: translate(4px, -2px); }
  60%      { clip-path: inset(70% 0 10% 0); transform: translate(-3px, 1px); }
  80%      { clip-path: inset(10% 0 80% 0); transform: translate(3px, -3px); }
}

@keyframes roy-visual-glitch-2 {
  0%, 100% { clip-path: inset(95% 0 0 0);  transform: translate(0); }
  25%      { clip-path: inset(40% 0 30% 0); transform: translate(4px, -2px); }
  50%      { clip-path: inset(60% 0 10% 0); transform: translate(-4px, 2px); }
  75%      { clip-path: inset(20% 0 60% 0); transform: translate(3px, -3px); }
}

visual-prism:
/* Prism Split */
.roycss-visual-prism {
  position: relative;
  inline-size: 180px;
  block-size: 120px;
  border-radius: 14px;
  border: none;
  background: radial-gradient(circle at 50% 50%, oklch(0.228 0.038 282.93) 0%, oklch(0.147 0.011 285.01) 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.roycss-visual-prism > div { display: none; }

.roycss-visual-prism::before,
.roycss-visual-prism::after {
  content: '';
  position: absolute;
  inset-block-start: 50%;
  inset-inline-start: 50%;
  inline-size: 90px;
  block-size: 90px;
  background: conic-gradient(
    from 0deg,
    oklch(0.637 0.208 25.33),
    oklch(0.769 0.165 70.08),
    oklch(0.795 0.162 86.05),
    oklch(0.723 0.192 149.58),
    oklch(0.715 0.126 215.22),
    oklch(0.623 0.188 259.81),
    oklch(0.606 0.219 292.72),
    oklch(0.656 0.212 354.31),
    oklch(0.637 0.208 25.33)
  );
  clip-path: polygon(50% 0%, 100% 100%, 0% 100%);
  transform-origin: 50% 60%;
}

.roycss-visual-prism::before {
  filter: blur(2px);
  animation: roy-visual-prism 4s linear infinite;
}

.roycss-visual-prism::after {
  filter: blur(10px);
  opacity: 0.55;
  animation: roy-visual-prism 4s linear infinite reverse;
}

@keyframes roy-visual-prism {
