  78% { transform: scale(0.98, 1.02); }
  100% { transform: scale(1); }
}

apple-squish-out:
/* Apple Squish Out */
.roycss-apple-squish-out {
  animation: roy-apple-squish-out 0.55s cubic-bezier(0.32, 0.72, 0, 1) both;
}

@keyframes roy-apple-squish-out {
  0% { opacity: 1; transform: scale(1); }
