  15% { transform: translateY(0); opacity: 1; }
  30% { transform: translateY(-22%); }
  45% { transform: translateY(0); }
  60% { transform: translateY(-8%); }
  75% { transform: translateY(0); }
  88% { transform: translateY(-2%); }
  100% { transform: translateY(0); }
}

natural-drop:
