  55% { transform: translateY(0) scaleY(0.85); }
  65% { transform: translateY(-30%) scaleY(1.05); }
  80% { transform: translateY(0) scaleY(0.95); }
  90% { transform: translateY(-8%) scaleY(1.02); }
  100% { transform: translateY(0) scaleY(1); }
