.roycss-linear-aurora-glow::before,
.roycss-linear-aurora-glow::after {
  content: "";
  position: absolute;
  inline-size: 60%;
  block-size: 60%;
  border-radius: 50%;
  filter: blur(60px);
  opacity: 0.5;
  animation: roy-aurora-float 10s ease-in-out infinite;
}
.roycss-linear-aurora-glow::before {
  background: radial-gradient(circle, oklch(0.567 0.159 275.21), transparent 70%);
