  inset-inline-start: -10%;
}
.roycss-linear-aurora-glow::after {
  background: radial-gradient(circle, oklch(0.606 0.219 292.72), transparent 70%);
  inset-block-end: -20%;
  inset-inline-end: -10%;
  animation-delay: -5s;
}

