@supports not (mask: linear-gradient(110deg, oklch(0 0 0), transparent)) {
  .roycss-mask-linear-wipe::before {
    animation: roy-b10-mlw-fb 4s ease-in-out infinite;
  }
  @keyframes roy-b10-mlw-fb {
    0%, 100% { clip-path: inset(0 100% 0 0); }
