    box-shadow: inset 0 1px 3px color-mix(in oklch, oklch(0 0 0) 40%, transparent), 0 4px 12px color-mix(in oklch, oklch(0 0 0) 40%, transparent);
  }
}
@keyframes roy-b12-toggle-knob {
