    linear-gradient(oklch(0.279 0.037 260.03), oklch(0.279 0.037 260.03)),
    linear-gradient(oklch(0.279 0.037 260.03), oklch(0.279 0.037 260.03)),
    linear-gradient(oklch(0.279 0.037 260.03), oklch(0.279 0.037 260.03)),
    linear-gradient(oklch(0.279 0.037 260.03), oklch(0.279 0.037 260.03)),
    linear-gradient(oklch(0.279 0.037 260.03), oklch(0.279 0.037 260.03)),
    linear-gradient(oklch(0.279 0.037 260.03), oklch(0.279 0.037 260.03));
