  position: relative;
  box-shadow: 0 0 0 4px color-mix(in oklch, oklch(0.637 0.208 25.33) 15%, transparent), 0 4px 12px color-mix(in oklch, oklch(0 0 0) 30%, transparent);
  animation: roy-b12-shake-error 3s ease-in-out infinite;
