    top: 0;
    left: 0;
    right: 0;
    height: 100%;
    border-top: 2px solid oklch(0.541 0.247 293.01);
    border-bottom: 2px solid oklch(0.541 0.247 293.01);
    transform: scaleX(0);
    transition: transform 0.4s ease, border-color 0.3s ease;
}
/* left + right lines */
